import Foundation

/// Standard passenger-vehicle GDL summaries. Sources are official licensing agencies,
/// manuals or statutes, checked 2026-10-19. Do not infer a license upgrade from age.
/// See docs/driving-restrictions.md for coverage and maintenance requirements.
enum DrivingRestrictionCatalog {
    private static func guide(_ code: String, _ name: String, _ source: String,
                              supervisor: String = "A licensed supervising adult must accompany you. The official permit guide specifies eligible ages, relationships and driving experience.",
                              permit: String = "No solo driving. Follow the permit’s passenger, time and supervisor conditions in the official guide.",
                              age: Int = 18, night: String, exceptions: String,
                              passengers: String, family: String,
                              other: String = "Follow seat-belt, child-restraint, phone-use and printed license conditions. Check the official guide for required documents and exceptions.",
                              fullAgeRules: Bool = false, additionalSources: [String] = []) -> StateDrivingGuide {
        StateDrivingGuide(id: code, name: name, sources: [source] + additionalSources + (permitGuides[code].map { [$0.url] } ?? []),
                          permitSupervisor: permitGuides[code]?.supervisor ?? supervisor, permitConditions: permitGuides[code]?.conditions ?? permit, teenAgeLimit: age,
                          night: night, nightExceptions: exceptions, passengers: passengers,
                          passengerExceptions: family, other: other, ageRulesOnFullLicense: fullAgeRules)
    }

    private struct PermitGuide {
        let supervisor: String
        let conditions: String
        let url: String
    }

